#!/usr/bin/env node
/**
 * update-streak.mjs — draws assets/streak-buddy.svg from the REAL GitHub
 * contribution calendar (GraphQL), so the card is regenerated by our own
 * workflow instead of a third-party widget with a 24-hour cache.
 *
 * Numbers produced (all from GitHub, nothing invented):
 *   - current streak   : consecutive days with >= 1 contribution, ending today
 *   - longest streak   : best run in the last 365 days
 *   - contributions    : total contributions in the last 365 days
 *   - today            : contributions recorded so far today
 *   - active days      : days with at least one contribution
 *
 * Honesty guard: if GitHub returns zero contributions the SVG is NOT written,
 * so the README can never show an empty or fake card.
 */

import { writeFileSync, mkdirSync } from 'node:fs';
import { dirname } from 'node:path';

const OWNER = process.env.GITHUB_REPOSITORY_OWNER || 'SudhirDevOps1';
const TOKEN = process.env.GITHUB_TOKEN || '';
const OUT = 'assets/streak-buddy.svg';

const QUERY = `
  query ($login: String!) {
    user(login: $login) {
      contributionsCollection {
        contributionCalendar {
          totalContributions
          weeks {
            contributionDays {
              date
              contributionCount
            }
          }
        }
      }
    }
  }
`;

async function fetchCalendar() {
  if (!TOKEN) throw new Error('GITHUB_TOKEN is required to read the contribution calendar');

  const res = await fetch('https://api.github.com/graphql', {
    method: 'POST',
    headers: {
      Authorization: `Bearer ${TOKEN}`,
      'User-Agent': `${OWNER}-streak-buddy`,
      'Content-Type': 'application/json',
    },
    body: JSON.stringify({ query: QUERY, variables: { login: OWNER } }),
  });

  const json = await res.json().catch(() => ({}));
  if (!res.ok || json.errors) {
    const detail = json.errors?.[0]?.message || `HTTP ${res.status}`;
    throw new Error(`GitHub GraphQL failed: ${detail}`);
  }

  const calendar = json.data?.user?.contributionsCollection?.contributionCalendar;
  if (!calendar || !Array.isArray(calendar.weeks)) {
    throw new Error('GitHub GraphQL returned no contribution calendar');
  }
  return calendar;
}

function analyse(calendar) {
  const days = calendar.weeks
    .flatMap((week) => week.contributionDays)
    .slice()
    .sort((a, b) => a.date.localeCompare(b.date));

  if (days.length === 0) throw new Error('Contribution calendar is empty');

  const last = days[days.length - 1];
  const today = last.contributionCount;

  // Anchor on yesterday when today has no contribution yet, so the streak is
  // not reported as broken before the day is actually over.
  let anchor = days.length - 1;
  if (days[anchor].contributionCount === 0) anchor -= 1;

  let current = 0;
  for (let i = anchor; i >= 0 && days[i].contributionCount > 0; i--) current++;

  let longest = 0;
  let run = 0;
  let bestDay = days[0];
  for (const day of days) {
    if (day.contributionCount > 0) {
      run++;
      if (run > longest) longest = run;
    } else {
      run = 0;
    }
    if (day.contributionCount > bestDay.contributionCount) bestDay = day;
  }

  return {
    total: Number(calendar.totalContributions) || days.reduce((s, d) => s + d.contributionCount, 0),
    current,
    longest,
    today,
    activeDays: days.filter((d) => d.contributionCount > 0).length,
    bestDay,
    lastDate: last.date,
  };
}

const fmt = (n) => new Intl.NumberFormat('en-US').format(n);

function shortDate(iso) {
  return new Date(`${iso}T12:00:00Z`).toLocaleDateString('en-GB', {
    timeZone: 'Asia/Kolkata',
    day: '2-digit',
    month: 'short',
    year: 'numeric',
  });
}

function render(stats) {
  const streakLabel = stats.current === 1 ? 'DAY' : 'DAYS';
  const longestLabel = stats.longest === 1 ? 'DAY' : 'DAYS';

  return `<svg xmlns="http://www.w3.org/2000/svg" width="620" height="200" viewBox="0 0 620 200" role="img" aria-label="Contribution streak: ${stats.current} days current, ${stats.longest} days longest, ${fmt(stats.total)} total contributions">
  <defs>
    <linearGradient id="bg" x1="0" y1="0" x2="1" y2="1">
      <stop offset="0%" stop-color="#0D1117"/>
      <stop offset="100%" stop-color="#161B22"/>
    </linearGradient>
    <linearGradient id="accent" x1="0" y1="0" x2="0" y2="1">
      <stop offset="0%" stop-color="#36BCF7"/>
      <stop offset="100%" stop-color="#A855F7"/>
    </linearGradient>
    <linearGradient id="num" x1="0" y1="0" x2="1" y2="0">
      <stop offset="0%" stop-color="#36BCF7"/>
      <stop offset="100%" stop-color="#A855F7"/>
    </linearGradient>
    <style>
      .t { font-family: 'Segoe UI', Helvetica, Arial, sans-serif; }
      .label { font-size: 11px; letter-spacing: 2.4px; fill: #8B949E; font-weight: 600; }
      .num { font-size: 38px; font-weight: 700; fill: url(#num); }
      .unit { font-size: 12px; fill: #6E7681; font-weight: 600; letter-spacing: 1px; }
      .foot { font-size: 10.5px; fill: #6E7681; letter-spacing: 0.4px; }
      .dot { fill: #3FB950; animation: pulse 2.4s ease-in-out infinite; transform-origin: 561px 28px; }
      @keyframes pulse { 0%, 100% { opacity: 1; transform: scale(1); } 50% { opacity: .35; transform: scale(.7); } }
      .bar { animation: glow 3.6s ease-in-out infinite; }
      @keyframes glow { 0%, 100% { opacity: 1; } 50% { opacity: .55; } }
    </style>
  </defs>

  <rect x="0.5" y="0.5" width="619" height="199" rx="16" fill="url(#bg)" stroke="#30363D"/>
  <rect class="bar" x="0" y="28" width="4" height="144" rx="2" fill="url(#accent)"/>

  <text class="t label" x="30" y="36">STREAK BUDDY</text>
  <circle class="dot" cx="561" cy="28" r="4"/>
  <text class="t label" x="590" y="32" text-anchor="end" style="letter-spacing:1.2px">LIVE</text>

  <text class="t label" x="30" y="78">CURRENT</text>
  <text class="t num" x="30" y="122">${stats.current}</text>
  <text class="t unit" x="30" y="142">${streakLabel} IN A ROW</text>

  <line x1="206" y1="60" x2="206" y2="152" stroke="#21262D"/>

  <text class="t label" x="236" y="78">LONGEST</text>
  <text class="t num" x="236" y="122">${stats.longest}</text>
  <text class="t unit" x="236" y="142">${longestLabel} · RECORD</text>

  <line x1="412" y1="60" x2="412" y2="152" stroke="#21262D"/>

  <text class="t label" x="442" y="78">TOTAL · 365d</text>
  <text class="t num" x="442" y="122">${fmt(stats.total)}</text>
  <text class="t unit" x="442" y="142">CONTRIBUTIONS</text>

  <text class="t foot" x="30" y="180">@${OWNER} · ${stats.today} today · ${stats.activeDays} active days · best day ${fmt(stats.bestDay.contributionCount)}</text>
  <text class="t foot" x="590" y="180" text-anchor="end">updated ${shortDate(stats.lastDate)}</text>
</svg>
`;
}

async function main() {
  const calendar = await fetchCalendar();
  const stats = analyse(calendar);

  if (stats.total <= 0) {
    throw new Error('Refusing to draw a streak card with zero contributions');
  }

  const svg = render(stats);
  mkdirSync(dirname(OUT), { recursive: true });
  writeFileSync(OUT, svg, 'utf8');

  console.log(
    `Wrote ${OUT} — current ${stats.current}d, longest ${stats.longest}d, ` +
      `${fmt(stats.total)} contributions (365d), ${stats.today} today, ` +
      `${stats.activeDays} active days.`
  );
}

main().catch((error) => {
  console.error(`::error::${error.message}`);
  process.exit(1);
});
